def apply_discount(subtotal, discount_code):
    """Apply a discount code to a subtotal.

    Args:
        subtotal: The original subtotal.
        discount_code: The discount code string. Pass None to skip discount.

    Returns:
        The discounted subtotal rounded to 2 decimal places.
    """
    if not discount_code or discount_code not in DISCOUNT_CODES:
        return round(float(subtotal), 2)

    discount_value = DISCOUNT_CODES[discount_code]

    # Handle percentage vs flat discount
    if discount_code in ["FLAT5"]:
        discounted = max(0, subtotal - discount_value)
    else:
        discount_percent = discount_value / 100.0
        discounted = subtotal * (1 - discount_percent)

    return round(discounted, 2)

def apply_discount(subtotal, discount_code=None):
    """Apply a discount code to a subtotal if provided.

    Args:
        subtotal: The original subtotal.
        discount_code: The discount code string (optional).

    Returns:
        The discounted amount rounded to 2 decimal places.

    Note:
        This function is idempotent and should only be called once during payment calculation.
    """
    if not discount_code:
        return round(float(subtotal), 2)

    if discount_code == "FLAT5":
        return round(float(subtotal) - 5.00, 2)

    discount_percent = DISCOUNT_CODES.get(discount_code.upper())
    if discount_percent is None:
        return round(float(subtotal), 2)

    discount_amount = float(subtotal) * (discount_percent / 100)
    return round(float(subtotal) - discount_amount, 2)
